insert into places (id, name, name_en, category, region_id, address, lat, lng, description, tags, view_heading, palette, created_at, updated_at) values
  ('kr-gangneung-anmok-coffee-street', '안목해변 커피거리', 'Anmok Beach Coffee Street', 'cafe', 'kr-gangneung-gyeonso', '강원 강릉시 견소동', 37.7726, 128.9475, '바다를 마주한 카페들이 줄지어 선 거리. 등 뒤에는 커피 내리는 소리, 눈앞에는 동해 파도가 있어요.', array['바다', '카페', '오션뷰']::text[], 65, array['#9ccfe8', '#3d6f8e']::text[], '2026-10-25T12:00:00+09:00', '2026-10-25T12:00:00+09:00'),
  ('kr-gangneung-gyeongpo-beach', '경포해변', 'Gyeongpo Beach', 'beach', 'kr-gangneung-anhyeon', '강원 강릉시 안현동', 37.8057, 128.908, '길게 뻗은 백사장과 소나무 숲. 강릉 바다의 대표 풍경이에요.', array['바다', '솔숲', '백사장']::text[], 55, array['#b5dcef', '#c9b38a']::text[], '2026-10-25T12:00:00+09:00', '2026-10-25T12:00:00+09:00'),
  ('kr-gangneung-ojukheon', '오죽헌', 'Ojukheon', 'heritage', 'kr-gangneung-jukheon', '강원 강릉시 죽헌동 율곡로3139번길 24', 37.7794, 128.8784, '율곡 이이가 태어난 집. 줄기가 까만 대나무, 오죽(烏竹)이 집을 둘러싸고 있어요.', array['대숲', '고택', '역사']::text[], 0, array['#cfe3c4', '#4f6b3d']::text[], '2026-10-25T12:00:00+09:00', '2026-10-25T12:00:00+09:00'),
  ('kr-gangneung-jungang-market', '강릉중앙시장', 'Gangneung Jungang Market', 'market', 'kr-gangneung-seongnam', '강원 강릉시 성남동 금성로 21', 37.7543, 128.8989, '닭강정, 장칼국수, 수제 어묵. 강릉 먹거리가 모두 모인 전통시장이에요.', array['시장', '먹거리']::text[], 90, array['#f2d6a2', '#8a5a3b']::text[], '2026-10-25T12:00:00+09:00', '2026-10-25T12:00:00+09:00'),
  ('jp-kyoto-arashiyama-bamboo-grove', '아라시야마 치쿠린', 'Arashiyama Bamboo Grove', 'forest', 'jp-kyoto-ukyoku', '일본 교토부 교토시 우쿄구 사가텐류지', 35.017, 135.6719, '하늘을 가릴 만큼 높이 자란 대나무 사이로 난 오솔길.', array['대숲', '산책']::text[], 0, array['#d8e8c0', '#3e5c2c']::text[], '2026-10-25T12:00:00+09:00', '2026-10-25T12:00:00+09:00');
